[
  {
    "statement": "A study evaluated the effects of using genetically modified crops that produce pesticide to replace conventional pesticide application.",
    "citations": []
  },
  {
    "statement": "The study on using genetically modified crops focused specifically on butterflies and moths.",
    "citations": []
  },
  {
    "statement": "A laboratory study examined maize genetically modified to express the Bacillus thuringiensis kurstaki (Btk) toxin.",
    "citations": []
  },
  {
    "statement": "The genetically modified maize was developed to act against the European corn borer.",
    "citations": []
  },
  {
    "statement": "A controlled study found that pollen from the genetically modified maize did not reduce the survival or growth of eastern tiger swallowtail caterpillars more than pollen from non-genetically modified maize.",
    "citations": []
  },
  {
    "statement": "A controlled study found that pollen from the genetically modified maize did not reduce the survival or growth of spicebush swallowtail caterpillars more than pollen from non-genetically modified maize.",
    "citations": []
  },
  {
    "statement": "No studies were found evaluating the community response to using genetically modified crops for pest control.",
    "citations": []
  }
]

[
  {
    "statement": "Based on limited evidence from one randomised, replicated, controlled study in Switzerland, mass-emergence devices showed mixed effectiveness.",
    "citations": []
  },
  {
    "statement": "A study found that mass-emergence devices increased parasitism at one site.",
    "citations": []
  },
  {
    "statement": "A study found that mass-emergence devices had no effect at another site.",
    "citations": []
  },
  {
    "statement": "Mass-emergence devices showed no effect on pest damage to horse chestnut trees.",
    "citations": []
  },
  {
    "statement": "The research on mass-emergence devices was conducted in urban areas rather than traditional farm settings.",
    "citations": []
  }
]
